/* @autogenerated */
import { Injectable, inject } from '@angular/core';
import { MatSnackBar } from '@angular/material/snack-bar';
import { HashMap, TranslocoService } from '@jsverse/transloco';
import { combineLatest, take } from 'rxjs';

type Level = 'success' | 'info' | 'error';

const DURATION: Record<Level, number> = { success: 3000, info: 5000, error: 8000 };

/**
 * Avisos breves (snackbar) con textos traducidos.
 *
 * @example
 * this.notify.success('common.notify.saved');
 */
@Injectable({ providedIn: 'root' })
export class NotifyService {
  private readonly snackBar = inject(MatSnackBar);
  private readonly transloco = inject(TranslocoService);

  success(key: string, params?: HashMap, actionKey?: string): void {
    this.open('success', key, params, actionKey);
  }

  info(key: string, params?: HashMap, actionKey?: string): void {
    this.open('info', key, params, actionKey);
  }

  error(key: string, params?: HashMap, actionKey?: string): void {
    this.open('error', key, params, actionKey);
  }

  private open(level: Level, key: string, params: HashMap | undefined, actionKey = 'common.notify.close'): void {
    // selectTranslate espera a que el fichero de idioma esté cargado
    combineLatest([this.transloco.selectTranslate(key, params), this.transloco.selectTranslate(actionKey)])
      .pipe(take(1))
      .subscribe(([message, action]) => {
        this.snackBar.open(message, action, { duration: DURATION[level], panelClass: 'notify-' + level });
      });
  }
}
